mapper.update:
UPDATE job_posting SET title = #{title}, description = #{description, jdbcType=CLOB}, pay = #{pay}, pay_type = #{payType}, work_period = #{workPeriod}, work_days = #{workDays}, start_time = #{startTime, jdbcType=VARCHAR}, end_time = #{endTime, jdbcType=VARCHAR}, time_negotiable = #{timeNegotiable, jdbcType=VARCHAR}, location = #{location, jdbcType=VARCHAR}, location_detail = #{locationDetail, jdbcType=VARCHAR},
/* 🚨 핵심: 값이 안 넘어오면 원래 DB에 있던 값을 그대로 유지해라 (NVL 처리) */ latitude = NVL(#{latitude, jdbcType=DOUBLE}, latitude), longitude = NVL(#{longitude, jdbcType=DOUBLE}, longitude), sido = NVL(#{sido, jdbcType=VARCHAR}, sido), gugun = NVL(#{gugun, jdbcType=VARCHAR}, gugun), dong = NVL(#{dong, jdbcType=VARCHAR}, dong), recruit_status = NVL(#{recruitStatus, jdbcType=VARCHAR}, recruit_status),
contact = #{contact, jdbcType=VARCHAR}, benefits = #{benefits, jdbcType=VARCHAR}, category = #{category}, deadline = #{deadline, jdbcType=DATE} WHERE posting_idx = #{postingIdx}

mapper.select:
        SELECT * FROM (
            SELECT a.*, ROWNUM rnum FROM (
                SELECT
                    posting_idx AS postingIdx,
                    title, employer, pay,
                    pay_type AS payType,
                    location, created_date AS createdDate,
                    category, work_period AS workPeriod,
                    recruit_status AS recruitStatus,
                    work_days AS workDays,
                    start_time AS startTime,
                    end_time AS endTime,
                    deadline 
                FROM job_posting


				        sido = #{sido}


				        AND gugun = #{gugun} 

				        AND dong = #{dong} 

                ORDER BY posting_idx DESC
            ) a WHERE ROWNUM <= #{offset} + #{size}
        ) WHERE rnum > #{offset}

SELECT posting_idx AS postingIdx, user_idx AS userIdx, region_idx AS regionIdx, pay_type AS payType, work_period AS workPeriod, work_days AS workDays, start_time AS startTime, end_time AS endTime, time_negotiable AS timeNegotiable, title, employer, description, pay, location, location_detail AS locationDetail, latitude, longitude, subway_info AS subwayInfo, contact, benefits, category, deadline, recruit_status, created_date, hit_count AS hitCount,
-- 관심(스크랩) 수 서브쿼리 추가 NVL((SELECT COUNT(*) FROM JOB_SCRAP js WHERE js.posting_idx = p.posting_idx), 0) AS likeCount, -- 지원자 수 서브쿼리 추가 NVL((SELECT COUNT(*) FROM JOB_APPLY ja WHERE ja.posting_idx = p.posting_idx), 0) AS applyCount
FROM job_posting p WHERE p.posting_idx = #{postingIdx}

mapper.update:
UPDATE job_posting
SET hit_count = hit_count + 1
WHERE posting_idx = #{postingIdx}

mapper.select:
SELECT jp.posting_idx AS postingIdx, jp.title, jp.employer, jp.pay, jp.pay_type AS payType, jp.location, jp.created_date AS createdDate, jp.category, jp.work_period AS workPeriod, jp.recruit_status AS recruitStatus, jp.work_days AS workDays, jp.start_time AS startTime, jp.end_time AS endTime, jp.deadline,
CASE WHEN js.posting_idx IS NOT NULL THEN 1 ELSE 0 END AS isScrapped
FROM job_posting jp
LEFT JOIN job_scrap js ON jp.posting_idx = js.posting_idx AND js.member_id = #{userIdx}
jp.sido = #{sido}
AND jp.gugun = #{gugun}
AND jp.dong = #{dong}
ORDER BY jp.created_date DESC

mapper.delete:
DELETE FROM JOB_SCRAP 
WHERE MEMBER_ID = #{memberId}
AND POSTING_IDX = #{postingIdx}

