mapper.select:
SELECT NVL(COUNT(*), 0)
FROM JOB_APPLY
WHERE posting_idx = #{postingIdx}

SELECT COUNT(*)
FROM JOB_APPLY
WHERE user_idx = #{userIdx}

SELECT COUNT(*)
FROM job_scrap
